const img=document.querySelector('#scene'),svg=document.querySelector('#boxes'),caption=document.querySelector('#frame-caption'),toggle=document.querySelector('#annotations');
let scenes=[];
function selectScene(i){const s=scenes[i];if(!s)return;img.src='assets/'+s.file;img.alt=`VisDrone validation frame ${i+1}, showing aerial traffic and pedestrians`;svg.setAttribute('viewBox',`0 0 ${s.width} ${s.height}`);svg.replaceChildren();for(const [x,y,w,h] of s.boxes){const r=document.createElementNS('http://www.w3.org/2000/svg','rect');for(const [k,v] of Object.entries({x,y,width:w,height:h,fill:'none',stroke:'#d8ee8c','stroke-width':1.5,'vector-effect':'non-scaling-stroke'}))r.setAttribute(k,v);svg.append(r)}caption.textContent=`FRAME 0${i+1} / ${s.count} annotated objects / ${s.width} × ${s.height}px`;document.querySelectorAll('[data-scene]').forEach(b=>{const active=+b.dataset.scene===i;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))})}
toggle.addEventListener('change',()=>{svg.style.display=toggle.checked?'block':'none'});document.querySelectorAll('[data-scene]').forEach(b=>b.addEventListener('click',()=>selectScene(+b.dataset.scene)));
fetch('scenes.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{scenes=data;selectScene(0)}).catch(()=>{caption.textContent='Annotation data unavailable. The source image is still shown.';toggle.disabled=true});
